mapper.select:
select a.id, a.weed_out_user_id, a.manage_time, a.cause_id, a.overdue, a.remarks, a.files, a.deleted, a.create_by, a.create_time, a.update_by, a.update_time, a.tenant, a.weed_out_numbers, a.status, a.process_instance_id from property_weed_out a inner join property_weed_out_relation b on a.id=b.weed_out_id inner join property_detailed c on b.property_id=c.id
a.manage_time =#{param.manageTime}
and a.cause_id =#{param.causeId}
and c.type_id =#{param.typeId}
and a.status =#{param.status}
and ( c.name like concat('%',#{param.keyword},'%') or a.weed_out_numbers like concat('%',#{param.keyword},'%') )
group by a.id order by a.manage_time desc,create_time desc
